CREATE TABLE agg_activity_ingestion ( source text PRIMARY KEY CHECK (trim(source) <> ''), checkpoint TEXT CHECK (checkpoint IS NULL OR json_type(checkpoint) = 'object'), seen_ids TEXT NOT NULL DEFAULT '[]', source_status TEXT CHECK (source_status IS NULL OR json_type(source_status) = 'object'), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
CREATE TABLE agg_activity_gaps ( id text PRIMARY KEY CHECK (trim(id) <> ''), source text NOT NULL CHECK (trim(source) <> ''), gap_from TEXT NOT NULL, gap_to TEXT NOT NULL, status text NOT NULL CHECK (status IN ('open', 'backfilled', 'unrecoverable')), detected_at TEXT NOT NULL, resolved_at TEXT, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), CONSTRAINT agg_activity_gaps_window_check CHECK (gap_to >= gap_from), CONSTRAINT agg_activity_gaps_resolved_check CHECK ( (status = 'open' AND resolved_at IS NULL) OR status <> 'open' ) );
CREATE INDEX agg_activity_gaps_source_from_idx ON agg_activity_gaps (source, gap_from);
CREATE TABLE agg_usage_snapshots ( snapshot_key text PRIMARY KEY CHECK (trim(snapshot_key) <> ''), ts TEXT NOT NULL, service_id text NOT NULL CHECK (trim(service_id) <> ''), metric_id text NOT NULL CHECK (trim(metric_id) <> ''), unit text NOT NULL CHECK (trim(unit) <> ''), source text NOT NULL CHECK (trim(source) <> ''), value TEXT NOT NULL CHECK ( json_type(value) IN ('integer', 'real') OR ( json_type(value) = 'object' AND json_type(value, '$.low') IN ('integer', 'real') AND json_type(value, '$.high') IN ('integer', 'real') ) ), limit_value REAL CHECK (limit_value IS NULL OR limit_value >= 0), resets_at TEXT, observed_by text NOT NULL CHECK (trim(observed_by) <> ''), recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
CREATE INDEX agg_usage_snapshots_ts_idx ON agg_usage_snapshots (ts DESC);
CREATE INDEX agg_usage_snapshots_service_ts_idx ON agg_usage_snapshots (service_id, ts DESC);
CREATE TABLE agg_store_documents ( store text PRIMARY KEY CHECK (trim(store) <> ''), version integer NOT NULL CHECK (version >= 1), document TEXT NOT NULL, writer text, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
